import ipaddress

class Subnet:
    def __init__(self, cidr):
        self.network = ipaddress.ip_network(cidr, strict=False)

    def __repr__(self):                       # for developers: could be pasted back into code
        return f"Subnet({str(self.network)!r})"

    def __str__(self):                        # for people
        return str(self.network)

    def __eq__(self, other):
        return isinstance(other, Subnet) and self.network == other.network

    def __hash__(self):                       # needed because we defined __eq__
        return hash(self.network)

    def __lt__(self, other):
        return self.network < other.network

    def __contains__(self, addr):
        return ipaddress.ip_address(addr) in self.network

    def __len__(self):
        return max(self.network.num_addresses - 2, 1)

    def __iter__(self):
        return iter(self.network.hosts())

    def __getitem__(self, index):
        return list(self.network.hosts())[index]

    def __bool__(self):
        return self.network.prefixlen < 32

