import functools, time

def timed(func):
    @functools.wraps(func)                     # copy name and docstring onto the wrapper
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        try:
            return func(*args, **kwargs)       # pass everything through, return the result
        finally:
            wrapper.last_duration = time.perf_counter() - start
    return wrapper

@timed
def sum_to(n):
    """Add the numbers 1..n."""
    return sum(range(1, n + 1))

print(sum_to(100_000))
