"""netmodel.py - the object model shared by the netkit tools."""
import ipaddress
import json
from dataclasses import asdict, dataclass, field
from enum import Enum


class PortState(Enum):
    OPEN = "open"
    CLOSED = "closed"
    FILTERED = "filtered"


@dataclass(frozen=True, order=True)
class Port:
    number: int
    proto: str = "tcp"

    def __post_init__(self):
        if not 1 <= self.number <= 65535:
            raise ValueError(f"port out of range: {self.number}")
        if self.proto not in ("tcp", "udp"):
            raise ValueError(f"unknown protocol: {self.proto!r}")

    def __str__(self):
        return f"{self.number}/{self.proto}"

    @classmethod
    def parse(cls, text):
        number, _, proto = text.partition("/")
        return cls(int(number), proto or "tcp")


@dataclass
class ScanResult:
    port: Port
    state: PortState
    rtt_ms: float | None = None

    @property
    def is_open(self):
        return self.state is PortState.OPEN


@dataclass(order=True)
class Host:
    ip: ipaddress.IPv4Address
    name: str = field(default="", compare=False)
